/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs them in order
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Read migration files and log them in order
 */
function migrate() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log('No migrations to apply.');
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in', MIGRATIONS_DIR);
      return;
    }

    console.log(`Found ${sqlFiles.length} migration(s):`);
    console.log('---');

    // Log each migration file
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log('---');
    console.log(`Would apply ${sqlFiles.length} migration(s).`);
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

// Run migration if this script is executed directly
if (require.main === module) {
  migrate();
}

module.exports = { migrate };

