#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL migration files from ./migrations/ directory and logs filenames in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Validates that a filename is a valid migration file
 * Migration files should follow the pattern: ####_description.sql
 * where #### is a number (version/timestamp)
 */
function isValidMigration(filename) {
  return /^\d+_.*\.sql$/.test(filename);
}

/**
 * Extracts the numeric prefix from migration filename
 * This is used for sorting migrations in order
 */
function getMigrationOrder(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : 0;
}

/**
 * Reads and processes all migration files
 */
async function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`📁 Migrations directory not found: ${MIGRATIONS_DIR}`);
      console.log('ℹ️  Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log('✓ Migrations directory created');
      return;
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    if (files.length === 0) {
      console.log('ℹ️  No migration files found');
      return;
    }

    // Filter for valid migration files and sort them
    const validMigrations = files
      .filter(isValidMigration)
      .sort((a, b) => {
        const orderA = getMigrationOrder(a);
        const orderB = getMigrationOrder(b);
        return orderA - orderB;
      });

    if (validMigrations.length === 0) {
      console.log('⚠️  No valid migration files found');
      console.log('ℹ️  Migration files should follow the pattern: ####_description.sql');
      return;
    }

    // Log each migration that would be applied
    console.log(`\n📋 Found ${validMigrations.length} migration(s) to apply:\n`);

    validMigrations.forEach((filename, index) => {
      const filepath = path.join(MIGRATIONS_DIR, filename);
      const fileSize = fs.statSync(filepath).size;
      console.log(`  ${index + 1}. ${filename} (${fileSize} bytes)`);
    });

    console.log('\n✓ Migration scan complete\n');

  } catch (error) {
    console.error('❌ Error reading migrations:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrations().catch((error) => {
  console.error('❌ Fatal error:', error);
  process.exit(1);
});

