const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads and processes SQL migration files
 * from the ./migrations/ directory in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * Files are sorted to ensure they are processed in order
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR)
      .filter(file => file.endsWith('.sql'))
      .sort();

    return files;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Log each migration file that would be applied
 */
function logMigrations() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const fileSize = fs.statSync(filePath).size;
    console.log(`${index + 1}. ${file} (${fileSize} bytes)`);
  });

  console.log(`\nTotal migrations: ${migrationFiles.length}`);
}

/**
 * Main execution
 */
if (require.main === module) {
  logMigrations();
}

module.exports = {
  getMigrationFiles,
  logMigrations
};

