 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env.test file and extract DATABASE_URL
 * @returns {string|null} The DATABASE_URL value or null if not found
 */
function getConnectionString() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Environment file not found: ${ENV_FILE}`);
      return null;
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Look for DATABASE_URL
      if (trimmedLine.startsWith('DATABASE_URL=')) {
        const connectionString = trimmedLine.substring('DATABASE_URL='.length).trim();
        // Remove quotes if present
        return connectionString.replace(/^["']|["']$/g, '');
      }
    }

    console.error('DATABASE_URL not found in .env.test');
    return null;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return null;
  }
}

/**
 * Log successful database connection (simulated)
 * @param {string} connectionString The database connection string
 */
function logConnection(connectionString) {
  // Mask sensitive parts of connection string for logging
  const maskedConnectionString = connectionString
    .replace(/(:\/\/)([^:]+):[^@]+(@)/, '$1[user]:[password]$3');

  console.log(`✓ Successfully connected to database: ${maskedConnectionString}\n`);
}

/**
 * Get all SQL migration files from the migrations directory
 * Files are sorted to ensure they are processed in order
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR)
      .filter(file => file.endsWith('.sql'))
      .sort();

    return files;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Log each migration file that would be applied
 */
function logMigrations() {
  // First, resolve and log database connection
  const connectionString = getConnectionString();
  if (!connectionString) {
    console.error('Failed to retrieve connection string. Aborting migrations.');
