const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parses a .env file and returns an object of environment variables
 */
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const env = {};

    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const [key, ...valueParts] = line.split('=');
      const trimmedKey = key.trim();
      const value = valueParts.join('=').trim();

      // Remove surrounding quotes if present
      const cleanValue = value.replace(/^["']|["']$/g, '');

      if (trimmedKey) {
        env[trimmedKey] = cleanValue;
      }
    });

    return env;
  } catch (error) {
    throw new Error(`Failed to read .env.test file: ${error.message}`);
  }
}

/**
 * Resolves the database connection string
 */
function resolveConnectionString() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`Environment file not found at ${ENV_FILE}`);
    }

    const env = parseEnvFile(ENV_FILE);
    const databaseUrl = env.DATABASE_URL;

    if (!databaseUrl) {
      throw new Error('DATABASE_URL not found in .env.test');
    }

    return databaseUrl;
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Logs a successful connection message
 */
function logConnection(databaseUrl) {
  console.log('✓ Successfully connected to database');
  console.log(`  Connection string: ${databaseUrl}`);
  console.log();
}

