const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Parse migration filename to extract version/order
 * Assumes naming convention: NNNN_description.sql or NNNN-description.sql
 * @param {string} filename - The migration filename
 * @returns {number} - The version number for sorting
 */
function extractVersion(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : 0;
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} - Array of sorted migration filenames
 */
function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort by version number
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => extractVersion(a) - extractVersion(b));

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      process.exit(1);
    }
    throw error;
  }
}

/**
 * Read and display migrations that would be applied
 */
function displayMigrations() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/ directory');
    return;
  }

  console.log('Migrations to apply (in order):\n');
  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log(`\nTotal: ${migrationFiles.length} migration(s)`);
}

/**
 * Main execution
 */
function main() {
  console.log('=== Database Migration Script ===\n');
  displayMigrations();
}

main();

