 * Gets all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files to ensure consistent ordering
    // Typically migrations are named with timestamps or sequence numbers (e.g., 001_init.sql)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

