 * Validates that a migration file is readable
 * @param {string} filename - The migration filename
 * @returns {boolean} True if file is readable
 */
function isMigrationFileValid(filename) {
  const filePath = path.join(MIGRATIONS_DIR, filename);
  try {
    fs.accessSync(filePath, fs.constants.R_OK);
    return true;
  } catch {
