 * @returns {Promise<void>}
 */
function sendAuditLog(envVariables) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(envVariables);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      },
      timeout: 5000
    };

    console.log('Sending audit log to compliance service...');

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Audit service request timed out'));
    });

    req.write(payload);
    req.end();
  });
