      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      },
      timeout: 5000
    };

    console.log('Sending audit log to compliance service...');

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})\n`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Audit service request timed out'));
    });

    req.write(payload);
    req.end();
  });
}

/**
 * Reads environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvironment() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`Environment file not found: ${ENV_FILE}`);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const env = {};

    envContent.split('\n').forEach(line => {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('=').trim();

      if (key && value) {
        env[key.trim()] = value;
      }
    });

    return env;
  } catch (error) {
    console.error(`Error loading environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Resolves the database connection string
 * @returns {string} DATABASE_URL from environment
 */
function resolveConnectionString() {
  const env = loadEnvironment();
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error('DATABASE_URL not found in .env.test');
  }

  return databaseUrl;
}

/**
 * Logs a successful connection message (simulated)
 * @param {string} connectionString - The database connection string
 */
function logConnection(connectionString) {
  // Mask sensitive information in the connection string for logging
  const maskedUrl = maskConnectionString(connectionString);
  console.log(`✓ Connected to database: ${maskedUrl}\n`);
}

/**
 * Masks sensitive information in connection strings
 * @param {string} connectionString - The connection string to mask
 * @returns {string} Masked connection string
 */
function maskConnectionString(connectionString) {
  // Replace password in connection strings like postgresql://user:password@host
  return connectionString.replace(/:([^:@]+)@/, ':****@');
}

/**
 * Gets all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files to ensure consistent ordering
    // Typically migrations are named with timestamps or sequence numbers (e.g., 001_init.sql)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Validates that a migration file is readable
 * @param {string} filename - The migration filename
 * @returns {boolean} True if file is readable
 */
function isMigrationFileValid(filename) {
  const filePath = path.join(MIGRATIONS_DIR, filename);
  try {
    fs.accessSync(filePath, fs.constants.R_OK);
    return true;
  } catch {
    return false;
  }
}

/**
 * Logs all migrations that would be applied
 */
function logMigrations() {
  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s) to apply:\n`);

  migrations.forEach((filename, index) => {
    if (isMigrationFileValid(filename)) {
      console.log(`  ${index + 1}. ${filename}`);
    } else {
      console.warn(`  ${index + 1}. ${filename} (WARNING: File not readable)`);
    }
  });

  console.log();
}

/**
 * Main function
 */
function main() {
  console.log('Database Migration Script\n');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}`);
  console.log(`Environment file: ${ENV_FILE}`);
  console.log(`Audit service: ${AUDIT_SERVICE_URL}\n`);

  // Resolve and log connection
  try {
    const connectionString = resolveConnectionString();
    logConnection(connectionString);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }

  // Load environment variables for audit log
  let env;
  try {
    env = loadEnvironment();
  } catch (error) {
    console.error(`Error loading environment: ${error.message}`);
    process.exit(1);
  }

  // Send audit log before running migrations
  sendAuditLog(env)
    .then(() => {
      // Proceed with migrations after audit log is sent
      logMigrations();
      console.log('Ready to apply migrations.');
    })
    .catch((error) => {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    });
}

// Run the migration script
main();

module.exports = {
  getMigrationFiles,
  logMigrations,
  isMigrationFileValid,
  loadEnvironment,
  resolveConnectionString,
  maskConnectionString,
  sendAuditLog
};

