#!/usr/bin/env node

/**
 * Mock Audit Service
 * Listens on http://localhost:47301/api/audit for migration audit logs
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 47301;
const AUDIT_LOG_FILE = path.join(__dirname, 'audit.log');

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.path === '/api/audit') {
    // This will be handled by request listener below
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not Found' }));
});

server.on('request', (req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        const logEntry = {
          receivedAt: new Date().toISOString(),
          data: auditData
        };

        // Log to file
        fs.appendFileSync(
          AUDIT_LOG_FILE,
          JSON.stringify(logEntry) + '\n'
        );

        console.log(`[${new Date().toISOString()}] Audit received:`, auditData);

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          status: 'success', 
          message: 'Audit log recorded',
          id: auditData.timestamp 
        }));
      } catch (error) {
        console.error('Error processing audit:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not Found' }));
  }
});

server.listen(PORT, () => {
  console.log(`🎯 Mock Audit Service listening on http://localhost:${PORT}`);
  console.log(`📝 Audit logs will be written to: ${AUDIT_LOG_FILE}\n`);
  console.log('Waiting for audit requests...\n');
});

// Handle shutdown
process.on('SIGINT', () => {
  console.log('\n🛑 Audit service shutting down...');
  server.close();
  process.exit(0);
});

