#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Advanced Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs them in order
 * 
 * Features:
 * - Reads SQL migrations from ./migrations/ directory
 * - Sorts migrations in order (supports timestamp and numeric naming)
 * - Logs each migration file with details
 * - Supports dry-run mode
 * - Validates SQL file format
 */

const migrationsDir = path.join(__dirname, 'migrations');
const isDryRun = process.argv.includes('--dry-run') || process.argv.includes('-n');
const showVerbose = process.argv.includes('--verbose') || process.argv.includes('-v');

/**
 * Get all migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
      process.exit(1);
    }

    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => path.extname(file) === '.sql');

    if (sqlFiles.length === 0) {
      console.log('No SQL migrations found.');
      return [];
    }

    // Sort files to ensure they run in order
    // Typically migrations are named with timestamps or sequence numbers
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Validate SQL file format
 * @param {string} content - SQL file content
 * @returns {boolean} True if valid SQL
 */
function isValidSQL(content) {
  const trimmed = content.trim();
  return trimmed.length > 0 && !trimmed.startsWith('-- ') === false;
}

/**
 * Apply migrations by logging each filename
 */
function applyMigrations() {
  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    return;
  }

  const mode = isDryRun ? 'DRY RUN' : 'EXECUTION';
  console.log(`\n📦 Database Migration Script - ${mode} Mode\n`);
  console.log(`Found ${migrations.length} migration(s) to apply:\n`);
  console.log('─'.repeat(70));

  let successCount = 0;

  migrations.forEach((filename, index) => {
    const filePath = path.join(migrationsDir, filename);

    try {
      // Read the migration file
      const content = fs.readFileSync(filePath, 'utf8');
      const stats = fs.statSync(filePath);

      // Log the filename with its order
      const padded = String(index + 1).padStart(String(migrations.length).length, ' ');
      console.log(`\n[${padded}/${migrations.length}] ${filename}`);
      console.log(`    Path: ${filePath}`);
      console.log(`    Size: ${content.length} bytes`);
      console.log(`    Modified: ${stats.mtime.toISOString()}`);

      if (showVerbose && content.length < 500) {
        console.log(`    Content preview:`);
        console.log(`    ${content.split('\n').slice(0, 3).join('\n    ')}`);
      }

      // Validate SQL
      if (!isValidSQL(content)) {
        console.log(`    ⚠️  Warning: File appears to be empty or invalid`);
        return;
      }

      // In a real implementation, you would execute the SQL here
      if (isDryRun) {
        console.log(`    Status: Would apply ✓ (DRY RUN)`);
      } else {
        console.log(`    Status: Would apply ✓ (READY)`);
      }

      successCount++;
    } catch (error) {
      console.error(`    ❌ Error: ${error.message}`);
    }
  });

  console.log('\n' + '─'.repeat(70));
  console.log(`\n✅ Summary: ${successCount}/${migrations.length} migrations ready to apply\n`);

  if (isDryRun) {
    console.log('ℹ️  This was a dry run. Use: node migrate.js (without --dry-run)\n');
  }
}

// Display help
function showHelp() {
  console.log(`
Database Migration Script

Usage: node migrate.js [options]

Options:
  --dry-run, -n     Run in dry-run mode (no changes applied)
  --verbose, -v     Show verbose output including SQL preview
  --help, -h        Show this help message

Examples:
  node migrate.js              # Apply all migrations
  node migrate.js --dry-run    # Preview migrations without applying
  node migrate.js --verbose    # Show detailed information
`);
}

// Handle help flag
if (process.argv.includes('--help') || process.argv.includes('-h')) {
  showHelp();
  process.exit(0);
}

// Run the migration script
applyMigrations();

