#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Advanced Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs them in order
 * Connects to database using DATABASE_URL from .env.test
 * 
 * Features:
 * - Reads SQL migrations from ./migrations/ directory
 * - Sorts migrations in order (supports timestamp and numeric naming)
 * - Logs each migration file with details
 * - Supports dry-run mode
 * - Validates SQL file format
 * - Resolves database connection string from .env.test
 */

const migrationsDir = path.join(__dirname, 'migrations');
const isDryRun = process.argv.includes('--dry-run') || process.argv.includes('-n');
const showVerbose = process.argv.includes('--verbose') || process.argv.includes('-v');

/**
 * Load environment variables from .env.test
 * @returns {object} Environment variables
 */
function loadEnvironment() {
  const envPath = path.join(__dirname, '.env.test');

  try {
    if (!fs.existsSync(envPath)) {
      console.error(`Error: .env.test file not found at ${envPath}`);
      return {};
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) {
        return;
      }

      const [key, value] = line.split('=');
      if (key && value) {
        envVars[key.trim()] = value.trim();
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error loading .env.test: ${error.message}`);
    return {};
  }
}

/**
 * Connect to database and verify connection string
 * @param {string} databaseUrl - Database connection string
 * @returns {boolean} True if connection string is valid
 */
function connectToDatabase(databaseUrl) {
  if (!databaseUrl) {
    console.error('❌ Error: DATABASE_URL not found in .env.test\n');
    return false;
  }

  try {
    // Parse the connection URL to extract details
    const url = new URL(databaseUrl);
    const dbType = url.protocol.replace(':', '');
    const host = url.hostname;
    const port = url.port;
    const database = url.pathname.replace('/', '');
    const username = url.username;

    console.log('✓ Database connection string resolved:');
    console.log(`  Protocol: ${dbType}`);
    console.log(`  Host: ${host}`);
    console.log(`  Port: ${port || 'default'}`);
    console.log(`  Database: ${database}`);
    console.log(`  User: ${username}`);
    console.log('✓ Successfully connected (mock)\n');

    return true;
  } catch (error) {
    console.error(`❌ Error parsing DATABASE_URL: ${error.message}\n`);
    return false;
  }
}

/**
 * Get all migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
      process.exit(1);
    }

    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => path.extname(file) === '.sql');

    if (sqlFiles.length === 0) {
      console.log('No SQL migrations found.');
      return [];
    }

    // Sort files to ensure they run in order
    // Typically migrations are named with timestamps or sequence numbers
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Validate SQL file format
 * @param {string} content - SQL file content
 * @returns {boolean} True if valid SQL
 */
function isValidSQL(content) {
  const trimmed = content.trim();
  return trimmed.length > 0 && !trimmed.startsWith('-- ') === false;
}

/**
 * Apply migrations by logging each filename
 */
function applyMigrations() {
  // Load environment variables
  const env = loadEnvironment();
  const databaseUrl = env.DATABASE_URL || process.env.DATABASE_URL;

  const mode = isDryRun ? 'DRY RUN' : 'EXECUTION';
  console.log(`\n📦 Database Migration Script - ${mode} Mode\n`);

  // Connect to database
  if (!connectToDatabase(databaseUrl)) {
    process.exit(1);
  }

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    return;
  }

  console.log(`Found ${migrations.length} migration(s) to apply:\n`);
  console.log('─'.repeat(70));

