      const content = fs.readFileSync(filePath, 'utf8');
      const stats = fs.statSync(filePath);

      // Log the filename with its order
      const padded = String(index + 1).padStart(String(migrations.length).length, ' ');
      console.log(`\n[${padded}/${migrations.length}] ${filename}`);
      console.log(`    Path: ${filePath}`);
      console.log(`    Size: ${content.length} bytes`);
      console.log(`    Modified: ${stats.mtime.toISOString()}`);

      if (showVerbose && content.length < 500) {
        console.log(`    Content preview:`);
        console.log(`    ${content.split('\n').slice(0, 3).join('\n    ')}`);
      }

