 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Reads all SQL files from the migrations directory and logs them in order
 */
async function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log('Migrations directory created.');
      return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in the migrations directory.');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    sqlFiles.forEach((file, index) => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      const stats = fs.statSync(filePath);
      console.log(`${index + 1}. ${file} (${stats.size} bytes)`);
    });

    console.log('\nMigrations are ready to be applied.');
    console.log('Note: This script currently logs migrations. Add database connection logic to actually apply them.');

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

// Run migrations if this script is executed directly
if (require.main === module) {
  runMigrations();
}

module.exports = { runMigrations };

