const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Reads DATABASE_URL from .env.test for connection information
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Manually parse .env file without external dependencies
 */
function loadEnvFile(filePath) {
  const env = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    });
  } catch (error) {
    throw new Error(`Failed to load .env.test file: ${error.message}`);
  }

  return env;
}

/**
 * Resolves and validates the database connection string
 */
function resolveConnectionString() {
  // Load environment from .env.test
  const envVars = loadEnvFile(ENV_FILE);
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    throw new Error(
      'DATABASE_URL not found in .env.test. ' +
      'Please ensure .env.test exists and contains a DATABASE_URL.'
    );
  }

  return databaseUrl;
}

/**
 * Logs a simulated database connection
 */
function logDatabaseConnection(connectionString) {
  // Mask sensitive information in the connection string for logging
  const maskedUrl = connectionString.replace(
