#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Error: migrations directory not found at ${migrationsDir}`);
      return [];
    }

    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main migration function
 * Logs each SQL file that would be applied in order
 */
function runMigrations() {
  console.log('🔄 Database Migration Script');
  console.log('============================\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('ℹ️  No migration files found in ./migrations/ directory');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\n✅ Migration script completed');
}

// Run migrations if this file is executed directly
if (require.main === module) {
  runMigrations();
}

// Export functions for use as a module
module.exports = {
  getMigrationFiles,
  runMigrations
};

