#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 * that would be applied, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR)
      .filter(file => file.endsWith('.sql'))
      .sort();

    return files;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Validate migration files (optional but good practice)
 * Checks that files follow naming convention: YYYYMMDD_HHmmss_description.sql
 * @param {string[]} files Array of migration filenames
 * @returns {boolean} True if all files are valid, false otherwise
 */
function validateMigrationFiles(files) {
  const migrationPattern = /^\d{14}_[a-z0-9_]+\.sql$/i;

  const invalidFiles = files.filter(file => !migrationPattern.test(file));

  if (invalidFiles.length > 0) {
    console.warn('Warning: Some migration files do not follow the naming convention (YYYYMMDDHHmmss_description.sql):');
    invalidFiles.forEach(file => console.warn(`  - ${file}`));
    return false;
  }

  return true;
}

/**
 * Log migration files that would be applied
 * @param {string[]} files Array of migration filenames
 */
function logMigrations(files) {
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });

  console.log('\n');
}

/**
 * Main function to run the migration script
 */
function main() {
  console.log('=== Database Migration Script ===\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migrations to apply.');
    process.exit(0);
  }

  // Validate migration files
  const isValid = validateMigrationFiles(migrationFiles);

  if (!isValid) {
    console.log('\nProceeding anyway...\n');
  }

  // Log migrations that would be applied
  logMigrations(migrationFiles);

  console.log('Ready to apply migrations.');
}

// Run the script
main();

