#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 * that would be applied, in order.
 * 
 * Connects to database using DATABASE_URL from .env.test
 * Sends connection details to audit service for compliance logging
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Load environment variables from .env.test file
 * @returns {Object} Environment variables object
 */
function loadEnv() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: .env.test file not found at ${ENV_FILE}`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      line = line.trim();

      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim();

      // Remove quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        envVars[key.trim()] = value.slice(1, -1);
      } else {
        envVars[key.trim()] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return {};
  }
}

/**
 * Resolve and validate database connection URL
 * @param {Object} envVars Environment variables object
 * @returns {string|null} Database URL or null if not found
 */
function getDatabaseUrl(envVars) {
  const dbUrl = envVars.DATABASE_URL;

  if (!dbUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    return null;
  }

  return dbUrl;
}

/**
 * Log database connection (simulated connection message)
 * @param {string} databaseUrl Database connection URL
 */
function logConnection(databaseUrl) {
  // Mask sensitive parts of the URL for logging
  const maskedUrl = databaseUrl.replace(
    /([a-z]+:\/\/)([^:]+):([^@]+)@/i,
    '$1$2:****@'
  );

  console.log(`✓ Connected to database: ${maskedUrl}\n`);
}

/**
 * Send environment configuration to audit service for compliance logging
 * @param {Object} envVars Environment variables object
 * @returns {Promise<void>}
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
      },
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent successfully (HTTP ${res.statusCode})\n`);
          resolve();
        } else {
          console.error(`✗ Audit service returned HTTP ${res.statusCode}`);
          console.error(`Response: ${data}\n`);
          reject(new Error(`Audit service error: HTTP ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error(`✗ Failed to connect to audit service: ${error.message}`);
      console.error(`Make sure the audit service is running at ${AUDIT_SERVICE_URL}\n`);
      reject(error);
    });

    req.write(payload);
    req.end();
  });
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR)
      .filter(file => file.endsWith('.sql'))
      .sort();

    return files;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Validate migration files (optional but good practice)
 * Checks that files follow naming convention: YYYYMMDD_HHmmss_description.sql
 * @param {string[]} files Array of migration filenames
 * @returns {boolean} True if all files are valid, false otherwise
 */
function validateMigrationFiles(files) {
  const migrationPattern = /^\d{14}_[a-z0-9_]+\.sql$/i;

  const invalidFiles = files.filter(file => !migrationPattern.test(file));

  if (invalidFiles.length > 0) {
    console.warn('Warning: Some migration files do not follow the naming convention (YYYYMMDDHHmmss_description.sql):');
    invalidFiles.forEach(file => console.warn(`  - ${file}`));
    return false;
  }

  return true;
}

/**
 * Log migration files that would be applied
 * @param {string[]} files Array of migration filenames
 */
function logMigrations(files) {
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });

  console.log('\n');
}

/**
 * Main function to run the migration script
 */
function main() {
  console.log('=== Database Migration Script ===\n');

  // Load environment variables
  const envVars = loadEnv();

  // Get and validate database URL
  const databaseUrl = getDatabaseUrl(envVars);
  if (!databaseUrl) {
    process.exit(1);
  }

  // Log connection
  logConnection(databaseUrl);

  // Send audit log to compliance service
  sendAuditLog(envVars)
    .then(() => {
      // Proceed with migrations after successful audit log
      const migrationFiles = getMigrationFiles();

      if (migrationFiles.length === 0) {
        console.log('No migrations to apply.');
        process.exit(0);
      }

      // Validate migration files
      const isValid = validateMigrationFiles(migrationFiles);

      if (!isValid) {
        console.log('\nProceeding anyway...\n');
      }

      // Log migrations that would be applied
      logMigrations(migrationFiles);

      console.log('Ready to apply migrations.');
    })
    .catch((error) => {
      console.error('Migration aborted due to audit service error.');
      process.exit(1);
    });
}

// Run the script
main();

