/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads migration files from the migrations directory
 * @returns {Promise<string[]>} Array of migration filenames sorted in order
 */
async function getMigrationFiles() {
  try {
    const files = await fs.promises.readdir(migrationsDir);

    // Filter for .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file) === '.sql')
      .sort();

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
      process.exit(1);
    }
    throw error;
  }
}

