    const files = await fs.promises.readdir(migrationsDir);

    // Filter for .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file) === '.sql')
      .sort();

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory not found at ${migrationsDir}`);
      process.exit(1);
    }
    throw error;
  }
}

/**
 * Resolves and validates the database connection string
 * @returns {string} The DATABASE_URL connection string
 */
function resolveConnectionString() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  return databaseUrl;
}

/**
 * Sanitizes connection string for logging (hides password)
 * @param {string} connectionString - The connection string to sanitize
 * @returns {string} Sanitized connection string
 */
function sanitizeConnectionString(connectionString) {
  // Hide password in format: protocol://user:password@host
  return connectionString.replace(/(:\/\/[^:]+:)[^@]+(@)/, '$1***$2');
}

/**
 * Logs database connection status
 */
function logDatabaseConnection() {
  const connectionString = resolveConnectionString();
  const sanitized = sanitizeConnectionString(connectionString);

  console.log(`✓ Connected to database: ${sanitized}\n`);
}

/**
 * Logs each migration file that would be applied
 */
async function logMigrations() {
  console.log('Migration Files (in order):');
  console.log('============================\n');

  const migrations = await getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  migrations.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log(`\nTotal migrations: ${migrations.length}`);
}

/**
 * Main execution
 */
async function main() {
  try {
    // Load environment variables from .env.test
    loadEnv();

    // Log database connection
    logDatabaseConnection();

    // Log migration files
    await logMigrations();
  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

// Run if executed directly
if (require.main === module) {
  main();
}

// Export functions for use as a module
module.exports = {
  getMigrationFiles,
  logMigrations,
  resolveConnectionString,
  logDatabaseConnection,
  sanitizeConnectionString,
  loadEnv,
};

