const http = require('http');

/**
 * Simple Audit Service for Testing
 * Listens on localhost:47301 and logs received audit data
 */

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);

        console.log('\n' + '='.repeat(60));
        console.log('AUDIT LOG RECEIVED');
        console.log('='.repeat(60));
        console.log(JSON.stringify(auditData, null, 2));
        console.log('='.repeat(60) + '\n');

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          status: 'success', 
          message: 'Audit log received',
          receivedAt: new Date().toISOString()
        }));
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          status: 'error', 
          message: 'Invalid JSON' 
        }));
      }
    });

    req.on('error', (error) => {
      console.error('Request error:', error.message);
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        status: 'error', 
        message: 'Server error' 
      }));
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ 
      status: 'error', 
      message: 'Not found' 
    }));
  }
});

server.listen(PORT, 'localhost', () => {
  console.log(`Audit Service listening on http://localhost:${PORT}/api/audit`);
  console.log('Press Ctrl+C to stop\n');
});

server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Error: Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

