#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and applies them in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL files from the migrations directory
 * @returns {Promise<string[]>} Array of migration filenames sorted in order
 */
async function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory not found at ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only .sql files
    const sqlFiles = files.filter(file => path.extname(file) === '.sql');

    // Sort files in order (typically by timestamp or version number)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    throw error;
  }
}

/**
 * Log each migration file that would be applied
 * @param {string[]} migrations Array of migration filenames
 */
function logMigrations(migrations) {
  if (migrations.length === 0) {
    console.log('No migrations found.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s) to apply:\n`);

  migrations.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });
}

/**
 * Main migration runner
 */
async function run() {
  try {
    console.log('Starting database migration...\n');

    const migrations = await getMigrationFiles();
    logMigrations(migrations);

    if (migrations.length > 0) {
      console.log('\nMigrations ready to be applied.');
      console.log('Note: This script currently logs migrations. Implement actual database connection to execute them.');
    }

    process.exit(0);
  } catch (error) {
    console.error('Migration failed:', error.message);
    process.exit(1);
  }
}

// Run the migration script
run();

