/**
 * Integration test script
 * Demonstrates migrate.js sending audit logs to the compliance service
 */

const http = require('http');
const { spawn } = require('child_process');

// Store received audit log
let receivedAuditLog = null;

/**
 * Start the mock audit service
 */
function startAuditService() {
  return new Promise((resolve) => {
    const server = http.createServer((req, res) => {
      if (req.method === 'POST' && req.path === '/api/audit') {
        let body = '';

        req.on('data', (chunk) => {
          body += chunk.toString();
        });

        req.on('end', () => {
          try {
            receivedAuditLog = JSON.parse(body);
            console.log('✓ Audit service received compliance log:\n');
            console.log(JSON.stringify(receivedAuditLog, null, 2));

            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ 
              success: true, 
              message: 'Audit log recorded successfully',
              timestamp: new Date().toISOString()
            }));
          } catch (error) {
            res.writeHead(400, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ 
              success: false, 
              error: 'Invalid JSON payload' 
            }));
          }
        });
      } else {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Not found' }));
      }
    });

    server.listen(47301, () => {
      console.log('🔐 Audit service started on http://localhost:47301/api/audit\n');
      resolve(server);
    });
  });
}

/**
 * Run the migration script
 */
function runMigration() {
  return new Promise((resolve, reject) => {
    const migration = spawn('node', ['migrate.js']);

    let output = '';

    migration.stdout.on('data', (data) => {
      output += data.toString();
      process.stdout.write(data);
    });

    migration.stderr.on('data', (data) => {
      output += data.toString();
      process.stderr.write(data);
    });

    migration.on('close', (code) => {
      if (code === 0) {
        resolve(output);
      } else {
        reject(new Error(`Migration script exited with code ${code}`));
      }
    });
  });
}

