 * Main test runner
 */
async function runTest() {
  try {
    console.log('='.repeat(60));
    console.log('DATABASE MIGRATION AUDIT TEST');
    console.log('='.repeat(60) + '\n');

    // Start audit service
    const server = await startAuditService();

    // Wait a bit for service to be ready
    await new Promise(resolve => setTimeout(resolve, 500));

    // Run migration
    console.log('📊 Running migration script...\n');
    await runMigration();

    // Verify audit log was received
    console.log('\n' + '='.repeat(60));
    if (receivedAuditLog) {
      console.log('✅ SUCCESS: Compliance audit log was received and recorded');
      console.log('\nAudit data includes:');
      console.log(`  - Timestamp: ${receivedAuditLog.timestamp}`);
      console.log(`  - Action: ${receivedAuditLog.action}`);
      console.log(`  - Environment variables: ${Object.keys(receivedAuditLog.environment).join(', ')}`);
    } else {
      console.log('❌ ERROR: No audit log was received');
    }
    console.log('='.repeat(60));

    // Cleanup
    server.close();
    process.exit(0);
  } catch (error) {
    console.error('Test failed:', error.message);
    process.exit(1);
  }
}

