/**
 * Reads and parses .env.test file to get environment variables
 * @returns {Object} Parsed environment variables
 */
function parseEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: .env.test file not found at: ${ENV_FILE}`);
      process.exit(1);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('=').trim();

      // Remove quotes if present
      const cleanValue = value.replace(/^['"]|['"]$/g, '');

      if (key) {
        envVars[key.trim()] = cleanValue;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Resolves and validates the database connection string
 * @returns {string} The DATABASE_URL from .env.test
 */
function resolveConnectionString() {
  const envVars = parseEnvFile();
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
