const fs = require('fs');
const path = require('path');

/**
 * Advanced Database Migration Script
 * 
 * Features:
 * - Reads SQL files from ./migrations/ directory
 * - Logs each filename in sorted order
 * - Tracks migration history (optional)
 * - Supports dry-run mode
 * - Handles migration naming conventions (prefix with numbers: 001_, 002_, etc.)
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const MIGRATIONS_LOG_FILE = path.join(__dirname, '.migrations');

/**
 * Get all migration files sorted in order
 * @returns {Array} Array of migration filenames
 */
function getMigrations() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory not found at: ${MIGRATIONS_DIR}`);
    return [];
  }

  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them
  return files
    .filter(file => file.endsWith('.sql'))
    .sort();
}

/**
 * Get previously applied migrations from log file
 * @returns {Set} Set of migration filenames that have been applied
 */
function getAppliedMigrations() {
  if (!fs.existsSync(MIGRATIONS_LOG_FILE)) {
    return new Set();
  }

  const content = fs.readFileSync(MIGRATIONS_LOG_FILE, 'utf8');
  return new Set(content.split('\n').filter(line => line.trim()));
}

/**
 * Log a migration as applied
 * @param {string} filename - Migration filename
 */
function logAppliedMigration(filename) {
  const timestamp = new Date().toISOString();
  const logEntry = `${filename} - ${timestamp}\n`;
  fs.appendFileSync(MIGRATIONS_LOG_FILE, logEntry);
}

/**
 * Main migration runner
 * @param {boolean} dryRun - If true, only logs what would be done
 */
async function runMigrations(dryRun = true) {
  try {
    const allMigrations = getMigrations();
    const appliedMigrations = getAppliedMigrations();

    if (allMigrations.length === 0) {
      console.log('No SQL migration files found in ./migrations/');
      return;
    }

    // Filter to only pending migrations
    const pendingMigrations = allMigrations.filter(
      file => !appliedMigrations.has(file)
    );

    if (pendingMigrations.length === 0) {
      console.log('✓ All migrations have been applied. Database is up to date.');
      return;
    }

    console.log(`\n${dryRun ? 'DRY RUN' : 'APPLYING'} ${pendingMigrations.length} pending migration(s):\n`);

    for (let i = 0; i < pendingMigrations.length; i++) {
      const filename = pendingMigrations[i];
      const filePath = path.join(MIGRATIONS_DIR, filename);
      const fileStats = fs.statSync(filePath);
      const fileContent = fs.readFileSync(filePath, 'utf8');

      console.log(`[${i + 1}] ${filename}`);
      console.log(`    Size: ${fileStats.size} bytes`);
      console.log(`    Lines: ${fileContent.split('\n').length - 1}`);

      if (!dryRun) {
        // Here you would execute the SQL against your database
        // Example: await executeSQL(fileContent);
        console.log(`    ✓ Executed`);
        logAppliedMigration(filename);
      }
    }

    const message = dryRun 
      ? `\n✓ Dry run complete. Run with --execute flag to apply migrations.`
      : `\n✓ Successfully applied ${pendingMigrations.length} migration(s).`;

    console.log(message);

  } catch (error) {
    console.error('✗ Error during migration:', error.message);
    process.exit(1);
  }
}

// Parse command line arguments
const args = process.argv.slice(2);
const executeMode = args.includes('--execute');
const listMode = args.includes('--list');

if (listMode) {
  // Just list all available migrations
  const migrations = getMigrations();
  if (migrations.length === 0) {
    console.log('No migrations found.');
  } else {
    console.log('Available migrations:\n');
    migrations.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
  }
} else {
  // Run migrations in the appropriate mode
  runMigrations(!executeMode);
}

