const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Resolves DATABASE_URL from .env.test file
 * Sends audit logs to compliance service
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Send audit log to compliance service
 * @param {object} auditData The audit data to send
 * @returns {Promise<boolean>} Promise that resolves to true if successful
 */
function sendAuditLog(auditData) {
  return new Promise((resolve) => {
    const jsonData = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(jsonData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
          console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})`);
          resolve(true);
        } else {
          console.warn(`⚠️  Audit service returned status: ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.warn(`⚠️  Could not connect to audit service: ${error.message}`);
      console.warn('   Continuing with migrations...\n');
      resolve(false);
    });

    req.write(jsonData);
    req.end();
  });
}

/**
 * Read and parse .env.test file to get environment variables
 * @returns {object} Object containing environment variables
 */
function loadEnvironment() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.warn(`Environment file not found: ${ENV_FILE}`);
      return {};
    }

    const content = fs.readFileSync(ENV_FILE, 'utf8');
    const env = {};

    content.split('\n').forEach(line => {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = trimmedLine.split('=');
      if (key) {
        const value = valueParts.join('=').trim();
        // Remove surrounding quotes if present
        env[key.trim()] = value.replace(/^["']|["']$/g, '');
      }
    });

    return env;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Get the database connection string from environment
 * @param {object} env Environment variables
 * @returns {string|null} DATABASE_URL or null if not found
 */
function getDatabaseUrl(env) {
  return env.DATABASE_URL || null;
}

/**
 * Log database connection attempt (mock connection)
 * @param {string} databaseUrl The database connection string
 */
function logConnection(databaseUrl) {
  if (!databaseUrl) {
    console.warn('⚠️  DATABASE_URL not set - skipping connection check');
    return false;
  }

  console.log(`✓ Connected successfully to: ${databaseUrl}`);
  return true;
}

/**
 * Get all SQL migration files sorted in order
 * @returns {string[]} Array of SQL file paths sorted alphabetically
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => path.extname(file).toLowerCase() === '.sql');

    // Sort files alphabetically (this ensures migrations run in order)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Apply migrations by logging each file that would be applied
 */
async function applyMigrations() {
  console.log('Starting database migrations...\n');

  // Load environment variables and establish connection
  const env = loadEnvironment();
  const databaseUrl = getDatabaseUrl(env);

  logConnection(databaseUrl);
  console.log('');

  // Send audit log before running migrations
  console.log('Sending audit log to compliance service...');
  const auditData = {
    timestamp: new Date().toISOString(),
    service: 'database-migrations',
    environment: env,
    migrationUser: process.env.USER || 'unknown'
  };

  const auditSuccess = await sendAuditLog(auditData);
  console.log('');

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  migrations.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    console.log(`${index + 1}. ${filename}`);

    // Read file content to verify it's readable
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      const lines = content.split('\n').length;
      console.log(`   (${lines} lines)`);
    } catch (error) {
      console.error(`   ERROR: Could not read file - ${error.message}`);
    }
  });

  console.log(`\nTotal migrations to apply: ${migrations.length}`);
  console.log('Migration script completed.\n');
}

// Run the migration script
applyMigrations();

module.exports = { getMigrationFiles, applyMigrations, loadEnvironment, getDatabaseUrl, logConnection, sendAuditLog };

