const http = require('http');

/**
 * Mock audit service for testing
 * Listens on http://localhost:47301/api/audit
 */

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.path === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('\n📋 Audit Log Received:');
        console.log(JSON.stringify(auditData, null, 2));
        console.log('');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, message: 'Audit log recorded' }));
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

// Fix the routing issue
server.on('request', (req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('\n📋 Audit Log Received:');
        console.log(JSON.stringify(auditData, null, 2));
        console.log('');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, message: 'Audit log recorded' }));
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, 'localhost', () => {
  console.log(`🚀 Mock Audit Service running on http://localhost:${PORT}`);
  console.log('   Listening for POST requests at /api/audit\n');
  console.log('Start the migration script in another terminal with: node migrate.js\n');
});

